import json
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
drafts = {}

def add(number, xml, reason, notes):
    assert number not in drafts
    drafts[number] = (xml.strip(), reason, notes)

add('121 K ter', '''
<p>Les entités juridiques déposent la déclaration relative à la taxe prévue à l'article 990 D du code général des impôts auprès des services suivants :</p>
<p>1. Les entités juridiques qui ont leur siège en France, ainsi que les autres entités juridiques qui y exercent leurs activités dans un ou plusieurs établissements, déposent cette déclaration au service des impôts du lieu de leur principal établissement ;</p>
<p>2. Les entités juridiques autres que celles mentionnées au 1 qui, directement ou par l'intermédiaire d'une autre entité juridique, possèdent un ou plusieurs immeubles situés en France ou sont titulaires de droits réels sur ces biens déposent cette déclaration au service des impôts compétent pour leurs obligations déclaratives relatives aux impôts autres que les impôts locaux et taxes assimilées. Si elles ne sont soumises à aucune de ces obligations déclaratives, elles déposent la déclaration au service des impôts des entreprises étrangères de la direction des impôts des non-résidents.</p>
''', "Réécriture à droit constant : chaque catégorie d'entités est désormais le sujet explicite de son obligation de dépôt. La règle subsidiaire applicable en l'absence d'autres obligations déclaratives est formulée séparément dans le 2. Aucune réforme de fond n'est appliquée à cette taxe.", "Les subdivisions 1 et 2, le renvoi à l'article 990 D du CGI, la détention indirecte et les droits réels sont conservés. Le principal établissement détermine le service du 1 ; le service des entreprises étrangères n'intervient au 2 qu'en l'absence des obligations déclaratives indiquées. Aucune baisse des droits de mutation ou de l'IS n'est transposée à cette taxe.")

add('121 VA', '''
<p>Les dispositions du II de l'article 1066 du code général des impôts peuvent s'appliquer aux établissements et organismes suivants :</p>
<p>Caisse des dépôts et consignations ;</p>
<p>Caisses d'épargne ;</p>
<p>Caisses d'épargne du Bas-Rhin, du Haut-Rhin et de la Moselle ;</p>
<p>Fonds social juif unifié ;</p>
<p>Sociétés mutualistes, unions de sociétés mutualistes et fédérations d'unions de sociétés mutualistes.</p>
''', "Réécriture à droit constant : la formule d'ouverture est simplifiée et chaque catégorie d'établissement ou d'organisme figure dans un alinéa distinct. Les dénominations et l'intégralité de la liste sont conservées ; aucune réforme de fond de l'enregistrement n'est introduite.", "Le II de l'article 1066 du CGI a été consulté dans le corpus : l'inscription sur cette liste ne dispense pas de respecter ses conditions d'acquisition pour le compte d'une association et de transfert de propriété. Le renvoi demeure inchangé et aucune éligibilité automatique n'est créée.")

add('121 Z quinquies', '''
<p>I. – Les personnes physiques qui résident habituellement dans la Principauté de Monaco, qu'elles aient ou non leur domicile fiscal en France, doivent souscrire auprès du service des impôts des particuliers de Nice Est-Ouest-Menton les déclarations suivantes :</p>
<p>1° La déclaration d'impôt sur le revenu ;</p>
<p>2° La déclaration d'impôt sur la fortune immobilière.</p>
<p>Les personnes physiques qui exercent une activité professionnelle dans la Principauté de Monaco et dont le domicile fiscal est situé ou réputé situé en France doivent également déposer auprès de ce service les déclarations spéciales prévues aux articles 53 A et 97 du code général des impôts.</p>
<p>II. – Les personnes physiques qui résident habituellement dans la Principauté de Monaco, qu'elles aient ou non leur domicile fiscal en France, doivent souscrire auprès du service départemental de l'enregistrement de Nice les déclarations suivantes :</p>
<p>1° La déclaration de don manuel ;</p>
<p>2° La déclaration de succession.</p>
''', "Réécriture à droit constant : les obligations déclaratives sont exprimées directement et les deux services destinataires sont distingués dans les I et II existants. La condition propre aux déclarations professionnelles est rendue plus lisible. Aucune réforme de fond du domicile fiscal ou des impôts concernés n'est appliquée.", "Maintien des deux listes 1° et 2°, des renvois aux articles 53 A et 97 et des dénominations exactes des services. La résidence habituelle à Monaco suffit pour les déclarations énumérées aux I et II, quel que soit le domicile fiscal ; les déclarations spéciales restent soumises à la double condition d'activité à Monaco et de domicile fiscal situé ou réputé situé en France.")

add('121 Z sexies', '''
<p>Les personnes morales ou organismes dont le siège est situé dans un Etat membre de l'Union européenne ou dans un Etat partie à l'accord sur l'Espace économique européen adressent les demandes d'agrément mentionnées aux 4 bis des articles 200 et 238 bis, au I de l'article 795-0 A et au douzième alinéa du I de l'article 978 du code général des impôts au service de la sécurité juridique et du contrôle fiscal de la direction générale des finances publiques. Ce service instruit ces demandes.</p>
''', "Réécriture à droit constant : les demandeurs deviennent le sujet de la phrase et la mission d'instruction du service fait l'objet d'une seconde phrase dans le même alinéa. Le champ territorial et les quatre fondements des agréments sont maintenus. Aucune réforme de fond des avantages fiscaux n'est introduite.", "Renvois aux 4 bis des articles 200 et 238 bis, au I de l'article 795-0 A et au douzième alinéa du I de l'article 978 conservés avec leur niveau de subdivision. Le corpus porte les articles 200 et 238 bis sous l'état ABROGE_DIFF : contrôler leur succession temporelle avant consolidation définitive, sans remplacer ici les renvois. La note source fixe l'entrée en vigueur de cette rédaction au 1er octobre 2020, en application de l'article 8 de l'arrêté du 15 juillet 2020 ; il ne s'agit pas d'une date de réforme nouvelle.")

add('121 quinquies DB quater', '''
<p>L'exonération de cotisation foncière des entreprises prévue à l'article 1465 du code général des impôts peut être accordée sur agrément, dans les conditions fixées aux articles 121 quinquies DB quinquies à 121 quinquies DB septies, 170 quinquies et 170 octies. Son octroi demeure soumis à l'appréciation des modalités techniques et financières des programmes présentés. Les entreprises intéressées doivent n'avoir commis, au cours des quatre ans précédant l'opération, aucune infraction fiscale exclusive de bonne foi, avoir déposé leur déclaration de résultat dans les délais légaux et être en situation régulière à l'égard des services de recouvrement (1).</p>
<p>(1) Pour les modalités et les dates de dépôt des demandes d'agrément, se reporter à l'arrêté du 16 décembre 1983 (J. O. du 19 et 20 octobre).</p>
''', "Réécriture à droit constant : la phrase unique est divisée, dans le même alinéa, entre le fondement de l'agrément, l'appréciation des programmes et les conditions fiscales cumulatives. La note figurant dans le texte est maintenue. Aucune suppression d'aide ou réforme de fond de la CFE n'est déduite des orientations générales de policy.json.", "Délai de quatre ans et caractère cumulatif des trois conditions fiscales conservés. Les articles 170 quinquies et 170 octies du corpus confirment les règles de compétence. Incohérences préexistantes conservées et signalées : la note (1) du texte renvoie à un arrêté du 16 décembre 1983 mais à un J. O. des 19 et 20 octobre ; source_notes_xml indique en outre « (1) Sans objet. ». Ne pas substituer silencieusement décembre à octobre ni supprimer le renvoi sans décision de consolidation. Les références historiques aux lois du 30 décembre 2009, du 4 février 1995 et du 30 décembre 2006 et à la circulaire du 26 novembre 2004 n'instituent aucune date de réforme future.")

add('121 quinquies DB quinquies', '''
<p>Peuvent obtenir l'agrément ouvrant droit à l'exonération temporaire de cotisation foncière des entreprises prévue à l'article 1465 du code général des impôts les entreprises qui réalisent les opérations énumérées ci-dessous (dans les zones définies par l'article 3 de l'arrêté du 16 décembre 1983, publié au Journal officiel des 19 et 20 décembre 1983, modifié par l'article 4 de l'arrêté du 12 juin 1990, publié au Journal officiel du 29 juin 1990, et par les arrêtés du 8 août 1990, publié au Journal officiel du 23 août 1990, et du 21 janvier 1991, publié au Journal officiel du 27 janvier 1991) (1) :</p>
<p>1° La reprise des moyens de production d'établissements industriels en difficulté, lorsque cette reprise est susceptible de permettre la poursuite durable de l'activité et le soutien de l'emploi. L'agrément ne peut être accordé que si le plan de reprise et de sauvegarde ou de redressement ainsi que le plan de financement correspondant ont été examinés par le comité départemental d'examen des problèmes de financement des entreprises (CODEFI) (ou par le comité régional de restructuration industrielle (CORRI)) (1) ou par le comité interministériel de restructuration industrielle (CIRI). Lorsque la reprise prend la forme d'une location-gérance, elle doit s'accompagner d'un engagement ferme de rachat des actifs dans un délai de trois ans. Une reprise réalisée par une personne physique ou morale qui contrôle directement ou indirectement l'établissement en difficulté ne peut être agréée ;</p>
<p>2° La reconversion d'une installation industrielle dépendant d'un secteur d'activité en déclin. Cette reconversion doit modifier de manière importante la nature des productions et entraîner un effort particulier d'investissement. Seuls les investissements nécessaires à cette modification peuvent bénéficier de l'exonération ;</p>
<p>3° La création ou l'extension de services de direction, d'études, d'ingénierie et d'informatique. (Les décentralisations désignent les transferts, hors du Bassin parisien défini à l'annexe III de l'arrêté du 12 juin 1990, publié au Journal officiel du 29 juin 1990, d'installations précédemment implantées dans la région parisienne définie à cette même annexe) (1).</p>
''', "Réécriture à droit constant : les trois opérations éligibles et leurs conditions sont formulées en phrases plus courtes, sans modifier les subdivisions. Le contrôle préalable des plans, le rachat en location-gérance, l'exclusion des reprises sous contrôle et la limitation des investissements de reconversion sont explicités. Aucune réforme de fond ou extinction de l'exonération n'est introduite.", "Les trois ans, tous les arrêtés, leurs dates de publication, les trois comités et la référence à l'annexe III de l'arrêté du 12 juin 1990 sont conservés. La note source déclare sans objet les passages marqués (1), relatifs aux zones, au CORRI et aux décentralisations : ces passages restent entre parenthèses avec leur appel de note, sans leur attribuer une portée nouvelle. Une suppression ou actualisation de ces mentions exige une consolidation expresse ; les références historiques des notes ne la réalisent pas à elles seules.")

add('121 quinquies DB sexies', '''
<p>Pour obtenir sur agrément l'exonération temporaire de cotisation foncière des entreprises prévue à l'article 1465 du code général des impôts, les entreprises doivent remplir les conditions d'emploi suivantes, appréciées selon les modalités de l'article 322 H de l'annexe III à ce code :</p>
<p>1° Les établissements repris ou reconvertis doivent compter les effectifs suivants :</p>
<p>a. Dans les départements d'outre-mer, en Corse, dans les zones d'économie rurale dominante et dans les zones montagnardes figurant à l'annexe II de l'arrêté du 12 juin 1990 (JO du 29) :</p>
<p>Au moins trente emplois dans les communes situées dans une unité urbaine d'au moins 50 000 habitants ;</p>
<p>Au moins quinze emplois dans les communes situées dans une unité urbaine d'au moins 15 000 habitants et de moins de 50 000 habitants ;</p>
<p>Au moins six emplois dans les autres communes ;</p>
<p>b. Dans les autres zones d'application de l'exonération temporaire :</p>
<p>Au moins trente emplois dans les communes situées dans une unité urbaine d'au moins 15 000 habitants ;</p>
<p>Au moins dix emplois dans les autres communes.</p>
<p>Dans toutes les zones d'application de l'exonération temporaire, les reprises doivent permettre de maintenir l'effectif permanent au niveau justifié par les plans de sauvegarde ou de redressement de l'entreprise. Si l'effectif initial n'est pas maintenu, l'exonération peut être limitée à une fraction de la valeur locative des installations. En cas de reconversion, l'effectif doit au moins être maintenu.</p>
<p>Ces conditions d'emploi doivent être remplies pendant toute la période d'exonération. A défaut, l'agrément est retiré dans les conditions prévues à l'article 1649 nonies A du code général des impôts ;</p>
<p>2° En cas de création (ou de décentralisation) (1) de services de direction, d'études, d'ingénierie et d'informatique, l'entreprise doit créer au moins vingt emplois. En cas d'extension de ces services, elle doit créer au moins dix emplois supplémentaires et porter l'effectif total de l'établissement à au moins vingt emplois. L'extension doit également accroître cet effectif total d'au moins 25 %, sauf si elle crée au moins cinquante emplois supplémentaires.</p>
<p>La création d'un nombre d'emplois permanents supérieur à ces minima peut être exigée en fonction du montant des investissements envisagés.</p>
<p>Les articles 322 I à 322 L de l'annexe III au code général des impôts s'appliquent aux créations et extensions de services de direction, d'études, d'ingénierie et d'informatique.</p>
''', "Réécriture à droit constant : les seuils territoriaux sont reformulés avec des bornes explicites ; les exigences propres à la reprise, à la reconversion et aux services sont énoncées en phrases distinctes au sein des alinéas existants. Aucune réforme de fond des effectifs ou de l'exonération n'est appliquée.", "Conservation des 1°, 2°, a et b et de leurs alinéas. Seuils maintenus : 30, 15 et 6 emplois au a ; 30 et 10 au b ; bornes de 50 000 et 15 000 habitants, avec inclusion de 15 000 et exclusion de 50 000 pour la tranche intermédiaire ; 20 emplois à la création, 10 supplémentaires et 20 au total à l'extension, progression de 25 % sauf création d'au moins 50 emplois. Les renvois aux articles 322 H et 322 I à 322 L ont été vérifiés dans le corpus. Le retrait reste soumis à l'article 1649 nonies A. La note (1) de la source indique que la décentralisation est sans objet ; la parenthèse et son appel sont conservés. La coquille « extention » est corrigée en « extension », sans changement de champ.")

add('121 quinquies DB septies', '''
<p>L'octroi sur agrément de l'exonération temporaire de cotisation foncière des entreprises peut être conditionné à la réalisation d'un montant minimum d'investissements.</p>
<p>Une opération qui supprime des emplois dans les autres établissements de l'entreprise ne peut bénéficier de cette exonération.</p>
''', "Réécriture à droit constant : la condition facultative d'investissement est rattachée à l'octroi de l'exonération et l'exclusion liée aux suppressions d'emplois est formulée avec l'opération comme sujet. Les deux alinéas sont maintenus ; aucune réforme de fond n'est appliquée.", "Aucun montant minimal chiffré n'est créé. L'interdiction liée aux suppressions d'emplois dans les autres établissements reste distincte du minimum d'investissement qui peut être exigé. La note historique relative aux lois du 30 décembre 2009 et du 30 décembre 2006 n'ajoute aucune transition nouvelle.")

add('121 quinquies-0 DC', '''
<p>La déclaration prévue à l'article 1498 bis du code général des impôts doit indiquer le montant annuel du loyer, hors charges et taxes, correspondant à l'année de dépôt de cette déclaration.</p>
''', "Réécriture à droit constant : l'objet de la déclaration et l'année à laquelle se rapporte le loyer sont exprimés dans une phrase directe. L'exclusion des charges et des taxes est maintenue ; aucune réforme de fond de l'évaluation locative n'est appliquée.", "Le renvoi à l'article 1498 bis a été vérifié dans le corpus. Le loyer reste annuel et se rapporte à l'année de dépôt, sans être remplacé par celui d'un exercice antérieur ni par un montant charges comprises. Le présent article ne modifie pas le champ des déclarants ou des locaux défini par l'article de renvoi.")

add('121 quinquies DC', '''
<p>Une commission consultative des évaluations foncières est instituée au chef-lieu de chaque département. Elle donne un avis sur la valeur des coefficients fixés en application de l'article 1518 du code général des impôts pour actualiser les évaluations des propriétés bâties et non bâties mentionnées à cet article.</p>
''', "Réécriture à droit constant : l'institution de la commission et sa mission consultative sont distinguées en deux phrases dans le même alinéa. Le terme « quotité » est remplacé par « valeur » pour désigner les coefficients. Aucune réforme de fond des évaluations foncières n'est introduite.", "L'article 1518 du CGI, consulté dans le corpus, renvoie aux articles 121 quinquies DC à DF pour la composition de la commission. Celle-ci demeure consultative et compétente pour les deux catégories de propriétés ; aucun pouvoir de fixation des coefficients ne lui est attribué.")

add('121 quinquies DD', '''
<p>La commission consultative des évaluations foncières comprend :</p>
<p>1° Le directeur départemental ou, le cas échéant, régional des finances publiques, ou son représentant, qui assure la présidence ;</p>
<p>2° Deux fonctionnaires de la direction générale des finances publiques ayant au moins le grade d'inspecteur principal ;</p>
<p>3° Deux représentants des collectivités locales ou de leurs groupements (communautés urbaines ou districts), désignés par le préfet ;</p>
<p>4° Des membres titulaires et suppléants représentant les contribuables concernés par l'actualisation, répartis comme suit :</p>
<p>a. Le président de la chambre départementale d'agriculture ou son représentant ;</p>
<p>b. Deux titulaires et deux suppléants représentant la fédération départementale des syndicats d'exploitants agricoles ;</p>
<p>c. Deux titulaires et deux suppléants représentant la fédération départementale des syndicats de la propriété agricole. Parmi eux, un titulaire et un suppléant doivent être propriétaires de bois et affiliés au syndicat départemental des propriétaires forestiers sylviculteurs ;</p>
<p>d. Les organismes représentatifs des propriétaires d'immeubles bâtis du département désignent trois titulaires et trois suppléants, à raison d'un titulaire et d'un suppléant choisis respectivement parmi les propriétaires de locaux d'habitation et les propriétaires d'établissements industriels situés dans le département ;</p>
<p>e. Les organismes représentatifs des locataires dans le département désignent deux titulaires et deux suppléants.</p>
<p>Si les fédérations ou syndicats départementaux mentionnés aux b et c du 4° ne procèdent pas à ces désignations, la chambre départementale d'agriculture désigne d'office les représentants des exploitants et des propriétaires agricoles, sur requête du directeur départemental ou, le cas échéant, régional des finances publiques.</p>
<p>Lorsque plusieurs organismes représentent les propriétaires ou les locataires d'immeubles bâtis dans le département et ne parviennent pas à un accord, le préfet désigne les membres de la commission sur proposition de ces organismes.</p>
<p>Les membres de la commission qui ne sont pas fonctionnaires sont nommés pour un an. Leur mandat est renouvelable par tacite reconduction.</p>
<p>Un inspecteur des finances publiques assure le secrétariat de la commission.</p>
''', "Réécriture à droit constant : la présidence, les désignations et la suppléance des carences sont formulées avec des sujets explicites. Les phrases relatives aux propriétaires forestiers et au mandat sont scindées dans leurs alinéas respectifs. Les effectifs et subdivisions sont conservés ; aucune réforme de fond de la composition n'est appliquée.", "Les 1° à 4°, les lettres a à e et les quatorze alinéas sont maintenus. Incohérence préexistante au d : trois titulaires et trois suppléants sont annoncés, mais la suite ne mentionne qu'un titulaire et un suppléant choisis « respectivement » parmi deux catégories de propriétaires. Le corpus reproduit cette ambiguïté ; ni siège supplémentaire ni nouvelle catégorie ne sont inventés. La mention des districts au 3° est également conservée, sans actualisation institutionnelle implicite. Mandat d'un an, tacite reconduction et grade minimal d'inspecteur principal maintenus.")

add('121 quinquies DE', '''
<p>La commission siège en deux formations spécialisées. L'une examine les coefficients d'actualisation des valeurs locatives des propriétés non bâties mentionnées à l'article 1518 du code général des impôts ; l'autre examine les coefficients applicables aux propriétés bâties mentionnées au même article.</p>
<p>La formation compétente pour les propriétés non bâties comprend les membres fonctionnaires mentionnés aux 1° et 2° de l'article 121 quinquies DD, les représentants des collectivités locales ou de leurs groupements, le représentant de la chambre départementale d'agriculture et les représentants des fédérations départementales de syndicats d'exploitants et de propriétaires agricoles.</p>
<p>La formation compétente pour les propriétés bâties mentionnées à l'article 1518 du code général des impôts comprend les membres fonctionnaires précités, les représentants des collectivités locales ou de leurs groupements et les membres désignés par les organismes représentatifs des propriétaires d'immeubles bâtis et des locataires.</p>
''', "Réécriture à droit constant : les deux compétences sont présentées séparément et les compositions sont énoncées sans l'incise « outre ». Les trois alinéas et la répartition des membres sont maintenus. Aucune réforme de fond de l'organisation de la commission n'est introduite.", "Les deux formations partagent les membres fonctionnaires et les représentants des collectivités ou groupements. Les représentants agricoles siègent dans la formation des propriétés non bâties ; ceux des propriétaires d'immeubles bâtis et des locataires dans l'autre. Renvois à l'article 1518 du CGI et aux 1° et 2° de l'article 121 quinquies DD conservés, sans modifier les effectifs ni résoudre l'ambiguïté préexistante du d du 4° de ce dernier article.")

add('121 quinquies DF', '''
<p>Chaque formation spécialisée de la commission se réunit lorsque le président la convoque. Elle peut désigner des rapporteurs et constituer des sous-commissions pour examiner des questions propres aux propriétés bâties ou non bâties.</p>
<p>La commission entend les fonctionnaires et toute personnalité dont elle souhaite recueillir l'avis.</p>
''', "Réécriture à droit constant : le pouvoir de convocation est exprimé à la voix active et les missions des rapporteurs et sous-commissions sont formulées plus directement. Les deux alinéas sont maintenus ; aucune réforme de fond des pouvoirs de la commission n'est appliquée.", "La désignation de rapporteurs et la constitution de sous-commissions demeurent facultatives et relèvent de chaque formation. Le pouvoir d'audition appartient toujours à la commission ; aucun avis conforme, délai ou obligation de comparution nouveau n'est créé.")

add('121 sexies', '''
<p>Pour l'application du 3° du B du V de l'article 1519 du code général des impôts, les exploitants de mines doivent transmettre chaque année à la préfecture, au cours du mois de janvier, un relevé nominatif des ouvriers et employés qu'ils occupent au 1er janvier. Ce relevé indique la commune du domicile de chacun de ces ouvriers. Les relevés sont communiqués aux maires des communes intéressées, qui doivent les renvoyer dans un délai de quinze jours en y joignant, s'il y a lieu, leurs observations. Après avis des services des mines et des impôts, le préfet rectifie les relevés si nécessaire et les arrête définitivement. Ces relevés servent de base à la répartition de l'année qui suit celle de leur établissement.</p>
''', "Réécriture à droit constant : les étapes d'établissement, de consultation, de rectification et d'arrêt définitif des relevés sont présentées dans des phrases successives au sein de l'alinéa unique. L'exploitant, les maires et le préfet ont chacun un rôle explicite. Aucune réforme de fond de la redevance des mines n'est appliquée.", "Le renvoi a été vérifié dans l'article 1519 du CGI : le 3° du B du V traite de la répartition liée au domicile des ouvriers et employés. La coquille source « de l'article 1519 du au code » est corrigée en « de l'article 1519 du code ». Autre imprécision préexistante conservée et signalée : la source exige un relevé des ouvriers et employés mais ne vise expressément que « chacun de ces ouvriers » pour la commune de domicile ; l'extension explicite de cette indication aux employés reste à coordonner. Janvier, situation au 1er janvier, délai de quinze jours et répartition l'année suivante sont conservés. La note source vise l'article 113-I-2° de la loi n° 2026-103 du 19 février 2026 ; la note de l'article 1519 exclut l'application de sa nouvelle rédaction au calcul de la redevance due au titre de 2026. Cette transition doit être respectée, sans inventer de date future.")

add('124', '''
<p>La déclaration prévue à l'article 1565 du code général des impôts précise la nature de l'établissement ou le genre de réunion ou de représentation. Pour un établissement ambulant, elle doit être renouvelée dans chaque commune où des représentations sont données.</p>
<p>Une nouvelle déclaration est également obligatoire lorsqu'un changement du caractère de l'établissement ou de la nature du spectacle doit modifier le taux de l'impôt applicable.</p>
''', "Réécriture à droit constant : le contenu de la déclaration, son renouvellement territorial pour les établissements ambulants et la nouvelle déclaration en cas de changement affectant le taux sont exprimés directement. Les deux alinéas sont maintenus ; aucune réforme de fond de cet impôt n'est introduite.", "Le renvoi à l'article 1565 du CGI est conservé. Cet article n'a pas été trouvé dans le corpus fourni : l'articulation du régime historique avec ses dispositions de référence doit être contrôlée avant consolidation, sans inventer de disposition de remplacement. La nouvelle déclaration du second alinéa reste liée à un changement devant modifier le taux, et non à tout changement de spectacle.")

add('126', '''
<p>Tout jeu d'argent est, en principe, considéré comme un jeu de hasard, qu'il s'agisse d'un jeu de cartes ou d'un autre jeu.</p>
<p>Un jeu d'argent peut toutefois être exceptionnellement reconnu comme un « jeu de commerce » si aucune personne ne peut parier sur les chances d'un joueur, si le prélèvement au profit de la cagnotte se limite à un droit fixe obligatoire par joueur et par séance, et si aucun jeu de hasard n'est pratiqué dans le même établissement. Le cercle ou la maison de jeux doit avoir déclaré le caractère propre à chaque jeu de commerce conformément aux prescriptions du ministre de l'intérieur, sans que celui-ci l'ait contesté. Sont des cercles de jeux les associations régies par la loi du 1er juillet 1901 dont les membres ont été autorisés par le ministre de l'intérieur à pratiquer les jeux de hasard, ainsi que les associations régies par la loi de 1901 dont les membres ont adressé à ce ministre la déclaration prévue pour les jeux de commerce.</p>
<p>Sont des maisons de jeux les établissements où sont pratiqués des jeux d'argent et qui ne relèvent d'aucune des catégories définies ci-dessus.</p>
''', "Réécriture à droit constant : le principe de qualification, les conditions cumulatives de l'exception et les définitions des cercles et maisons de jeux sont formulés plus directement. La structure en trois alinéas est conservée. Aucune réforme de fond de la police ou de la fiscalité des jeux n'est appliquée.", "Maintien de l'exception des jeux de commerce : absence de pari sur un joueur, droit fixe obligatoire par joueur et séance, absence de jeu de hasard dans le même établissement, déclaration conforme et non contestée. Les deux catégories d'associations régies par la loi de 1901 restent distinctes, ainsi que l'autorisation pour les jeux de hasard et la déclaration pour les jeux de commerce. La qualification des maisons de jeux reste résiduelle.")

add('126 F', '''
<p>Sont totalement exemptées de l'impôt sur les spectacles, en application du premier alinéa du b du 3° de l'article 1561 du code général des impôts, les compétitions relevant des activités sportives suivantes : aïkido, athlétisme, aviron, badminton, balle au tambourin, ballon au poing, ball-trap, base-ball, boxe française, canne, canoë-kayak, char à voile, escalade, escrime, football américain, gymnastique, haltérophilie, handball, hockey sur gazon, javelot-tir sur cible, jeu de paume, judo, karaté, kendo, longue paume, lutte, motonautisme, natation, parachutisme, patinage à roulettes, pelote basque, pentathlon, pétanque et jeu provençal, skate-board, ski, squash-raquettes, sports de boules, sports de quilles, surf, taekwondo, tennis de table, tir, tir à l'arc, trampoline, triathlon, twirling-bâton et volley-ball.</p>
''', "Réécriture à droit constant : les compétitions exonérées deviennent le sujet de la disposition, avec indication directe de l'exemption totale et de son fondement. La liste complète des activités est conservée dans son ordre d'origine. Aucune réforme de fond ni activité supplémentaire n'est introduite.", "Le renvoi au premier alinéa du b du 3° de l'article 1561 du CGI est maintenu à son niveau exact. L'article 1561 est absent du corpus fourni ; la portée actuelle de ce renvoi historique doit être contrôlée avant consolidation. Aucun sport de la liste n'est supprimé, regroupé avec une discipline voisine ou actualisé par analogie.")

add('127', '''
<p>Toute entrée, qu'elle soit payante, gratuite ou à prix réduit, doit donner lieu à la remise d'un billet extrait d'un carnet à souches. Le billet est délivré à la caisse au moment du paiement de la place et avant l'entrée dans la salle de spectacle. Il comporte deux parties : le spectateur conserve l'une et l'autre est retenue au contrôle. Chacune de ces parties et la souche qui reste attachée au carnet doivent porter, de manière apparente et imprimée, le nom de l'établissement, le numéro d'ordre du billet, la catégorie de place correspondante et le prix global payé par le spectateur ou, le cas échéant, la mention de gratuité.</p>
''', "Réécriture à droit constant : les obligations de délivrance, de séparation des deux parties et d'impression des mentions sont réparties entre quatre phrases dans le même alinéa. Aucune réforme de fond de la billetterie ou du mode de contrôle n'est appliquée.", "Entrées payantes, gratuites et à prix réduit maintenues. Le billet reste délivré à la caisse au paiement et avant l'entrée, avec une partie pour le spectateur, une au contrôle et la souche au carnet. Les mentions obligatoires, y compris la gratuité en remplacement du prix, doivent figurer de manière apparente et imprimée sur chacun des trois éléments. La référence au paiement est conservée telle que dans la source, bien que celle-ci vise aussi les entrées gratuites ; aucune dispense de billet n'en est déduite.")

add('128', '''
<p>Un carnet de billets à plein tarif, à prix réduit ou gratuits ne peut servir qu'à la catégorie de places qui y est indiquée. Chaque spectateur doit recevoir un billet, sauf pour les loges, avant-scènes et baignoires lorsqu'elles ne sont pas divisées.</p>
<p>Les carnets de billets doivent être numérotés selon une série ininterrompue et utilisés dans l'ordre numérique. L'agent de perception doit être informé lorsque, exceptionnellement, cet ordre n'est pas suivi ou lorsque la série est achevée. A défaut, les droits sont exigibles sur tous les billets manquants.</p>
<p>Les règles de délivrance des billets aux entrées énoncées ci-dessus s'appliquent aux billets pris en abonnement ou en location, pour lesquels des carnets spéciaux sont obligatoires. Une série de carnets doit être affectée à la location pour chaque représentation, en matinée ou en soirée, donnée aux différents jours de la semaine. Les carnets utilisés un jour ne peuvent resservir que le même jour de la semaine suivante.</p>
<p>Les billets pris en abonnement ou en location doivent porter leur date de validité, également inscrite sur la souche et sur le coupon de contrôle. A l'ouverture des bureaux, une feuille de location ou un plan réservé à la location et indiquant les places louées doit être remis à l'agent de perception.</p>
<p>Le numéro de la place est inscrit sur la partie du billet réservée au spectateur. Lors du passage dans la salle, le coupon de contrôle attenant est retenu. Les coupons doivent être classés séance tenante par catégorie et par numéro, puis remis à l'agent de perception lors de l'arrêté des comptes.</p>
<p>Lorsqu'après la délivrance de son billet un spectateur souhaite changer de place et que ce changement entraîne une augmentation de prix, le supplément doit être constaté par la délivrance, à la caisse, d'un billet supplémentaire extrait d'un carnet numéroté. Ce carnet doit être établi dans les mêmes conditions que les autres carnets. Le montant du supplément encaissé doit être imprimé sur la souche, le volant et le coupon de contrôle.</p>
<p>Les établissements peuvent demander l'autorisation de délivrer les billets au moyen de distributeurs automatiques. L'administration apprécie seule l'admission des demandes et les conditions de chaque autorisation. Elle peut toujours révoquer l'autorisation en cas d'abus.</p>
''', "Réécriture à droit constant : chacun des sept alinéas expose les obligations de billetterie par étapes, avec des phrases plus courtes. Les règles des abonnements, locations, suppléments et distributeurs sont intégralement reprises. Aucune réforme de fond ni substitution de la billetterie informatisée aux carnets n'est introduite.", "Les sept alinéas restent dans leur ordre, notamment celui des règles générales auxquelles renvoie l'article 129. Maintien de l'exception des loges, avant-scènes et baignoires non divisées, de la série ininterrompue, de l'information de l'agent et de l'exigibilité sur tous les billets manquants à défaut. Réemploi des carnets limité au même jour de la semaine suivante ; date sur billet, souche et coupon ; classement séance tenante ; supplément imprimé sur les trois éléments. L'autorisation des distributeurs reste soumise à l'appréciation exclusive de l'administration et révocable en cas d'abus. La double virgule du dernier alinéa source est corrigée sans effet juridique.")

add('129', '''
<p>Un établissement peut, sur sa demande, être autorisé à utiliser des carnets journaliers comportant, pour chaque catégorie de places, autant de billets que de places susceptibles d'être occupées.</p>
<p>Avant d'utiliser ces carnets, l'établissement doit fournir au service des douanes et droits indirects un relevé certifié indiquant exactement le nombre de places disponibles.</p>
<p>Le billet remis au spectateur doit mentionner la catégorie et le numéro de sa place, la date d'emploi du billet et le prix global payé. Ces mentions doivent aussi figurer sur la souche et le coupon de contrôle.</p>
<p>Lorsque les prix de location diffèrent de ceux pratiqués au bureau, une même série journalière ne peut être utilisée simultanément pour la location et pour le bureau.</p>
<p>Pour les entrées gratuites ou à tarif réduit, il est interdit d'utiliser les carnets journaliers affectés aux places à tarif normal. Les billets correspondants doivent être extraits de carnets ordinaires à série ininterrompue, établis dans les conditions de l'article 128. Cette obligation s'applique également aux billets de petite recette et aux suppléments liés aux changements de places. Dans la série journalière, les billets correspondant aux places gratuites ou à tarif réduit doivent être annulés et rester attachés à leur souche. Après chaque représentation, l'établissement doit enliasser et conserver les carnets de cette représentation, qui doivent contenir les billets non délivrés.</p>
''', "Réécriture à droit constant : l'autorisation, le relevé préalable et les mentions sont exprimés avec l'établissement pour sujet ; le dernier alinéa distingue les interdictions, les carnets de substitution, l'annulation et la conservation. Les cinq alinéas sont maintenus. Aucune réforme de fond du régime des carnets journaliers n'est appliquée.", "Le nombre de billets par catégorie reste égal au nombre de places susceptibles d'être occupées. Le relevé demeure certifié et préalable. L'interdiction d'utilisation simultanée d'une série ne vaut que si les prix de location et de bureau diffèrent. L'article 128 a été vérifié dans le corpus et son renvoi est conservé. Aucune des catégories particulières (gratuité, tarif réduit, petite recette, supplément de changement de place) n'est omise ; les billets annulés restent à la souche et les carnets conservent les billets non délivrés.")

add('130', '''
<p>Les fabricants, importateurs et marchands de carnets ou de rouleaux de billets d'entrée dans les salles de spectacles doivent souscrire une déclaration de profession au bureau de déclarations de la direction générale des douanes et droits indirects.</p>
<p>Ils doivent également déclarer leurs livraisons de billets aux exploitants de spectacles en précisant :</p>
<p>1° Les noms et adresses des établissements destinataires ;</p>
<p>2° Le nombre de billets livrés par catégorie de places, les numéros et la couleur des billets, ainsi que le prix des places.</p>
<p>Ces déclarations doivent être adressées, dans les huit jours suivant les livraisons, à la direction régionale des douanes et droits indirects dans le ressort de laquelle les salles de spectacles sont exploitées. Pour les livraisons à des exploitants de spectacles forains, elles doivent être adressées à la direction régionale des douanes et droits indirects des départements où ces exploitants ont leur domicile ainsi qu'à la direction régionale des départements où ils exercent leur activité.</p>
<p>Les exploitants de spectacles qui achètent leurs billets directement à l'étranger sont considérés comme des importateurs. Ils sont soumis aux déclarations prévues au présent article.</p>
<p>Les billets doivent porter lisiblement le nom du fabricant lorsqu'ils sont fabriqués en France, ou celui de l'importateur lorsqu'ils proviennent de l'étranger.</p>
<p>En cas de défaut de déclaration ou de fausse déclaration, le vendeur ou l'importateur est passible des droits afférents aux recettes représentées par les billets non déclarés.</p>
<p>Les exploitants de spectacles sont comptables des recettes que représentent les billets reçus.</p>
''', "Réécriture à droit constant : les catégories de déclarants, les livraisons à déclarer et les services destinataires sont énoncés directement. Les importations directes et les mentions sur les billets font l'objet de phrases plus lisibles, avec maintien des neuf alinéas et des 1° et 2°. Aucune réforme de fond ou nouvelle sanction n'est introduite.", "Délai de huit jours après livraison, double destination des déclarations pour les spectacles forains, assimilation des acheteurs directs à l'étranger aux importateurs et noms à faire figurer selon l'origine maintenus. Le vendeur ou l'importateur demeure passible des droits sur les recettes représentées par les billets non déclarés. Le dernier alinéa conserve la responsabilité comptable des exploitants pour les billets reçus ; aucune simple déclaration de livraison ne les en libère. Le bureau de déclarations et les directions régionales de la source ne sont pas remplacés par un service supposé actuel.")

add('131', '''
<p>Pour les représentations occasionnelles, toute dérogation aux règles des articles 127, 128 et 129 exige une autorisation préalable du service. Les cartes d'entrée établies doivent, dans tous les cas, être déclarées. Chaque carte doit porter un numéro et le prix d'entrée, et comporter un coupon détachable sur lequel sont imprimés le numéro de la carte, la catégorie et le prix. Ce coupon est retenu au contrôle. L'impôt est perçu d'après le nombre de cartes émises, après déduction des cartes invendues qui sont présentées au service.</p>
''', "Réécriture à droit constant : l'exigence d'autorisation préalable et les obligations propres aux cartes sont exprimées dans des phrases distinctes, au sein de l'alinéa unique. La base de perception reste le nombre de cartes émises diminué des invendus représentés. Aucune réforme de fond de l'impôt ou de la dérogation n'est appliquée.", "Renvois aux articles 127, 128 et 129 conservés. L'autorisation ne supprime pas l'obligation de déclarer les cartes. Le numéro et le prix figurent sur la carte ; le coupon détachable porte de manière imprimée le numéro, la catégorie et le prix. Les invendus ne sont déduits que s'ils sont représentés, sans déduction automatique sur simple affirmation.")

add('131 A', '''
<p>I. – Pour l'application de l'article 1564 du code général des impôts, les organisateurs de réunions sportives et les exploitants de spectacles peuvent recourir à un système informatisé. Ses caractéristiques et son fonctionnement doivent respecter le cahier des charges annexé à l'arrêté du 8 mars 1993 modifié.</p>
<p>II. – Les organisateurs de réunions sportives et les exploitants de spectacles mentionnés à l'article 1559 du code général des impôts doivent déclarer la mise en service de leur système informatisé de billetterie à la direction régionale des douanes et droits indirects dont ils dépendent. Cette déclaration doit intervenir au plus tard lors de la première utilisation du système.</p>
<p>Pour décrire le système utilisé, la déclaration doit comporter les mentions suivantes :</p>
<p>1° Le nom du logiciel, son numéro de version et, le cas échéant, sa date, ainsi que l'identité de son concepteur ou le nom du progiciel ;</p>
<p>2° La configuration informatique ;</p>
<p>3° Le système d'exploitation ;</p>
<p>4° Le langage de programmation ;</p>
<p>5° Le format du logiciel source ou exécutable fourni par le concepteur ;</p>
<p>6° La description fonctionnelle du système ;</p>
<p>7° Le fac-similé d'un billet, d'un coupon de gestion et d'un relevé de recettes ;</p>
<p>8° Les sécurités mises en œuvre.</p>
<p>Les modifications du système doivent être portées à la connaissance de l'administration dans les conditions prévues au premier alinéa.</p>
''', "Réécriture à droit constant : la faculté d'utiliser un système informatisé est distinguée de son obligation de conformité ; le destinataire et l'échéance de déclaration sont explicités en deux phrases dans le II. Les huit mentions et les alinéas restent en place. Aucune réforme de fond ni nouvelle exigence technique n'est ajoutée.", "Les I et II, les 1° à 8°, l'arrêté du 8 mars 1993 modifié et l'échéance de première utilisation sont conservés. Les articles 1559 et 1564 du CGI sont absents du corpus fourni : vérifier leur articulation temporelle avant consolidation, sans inventer de renvois de remplacement. Imprécision préexistante conservée au dernier alinéa : « au premier alinéa » n'indique pas expressément s'il s'agit du premier alinéa du II ; le I traite de conformité et le premier alinéa du II de déclaration. Cette référence doit être sécurisée par coordination expresse, sans déplacement des alinéas ni ajout silencieux des mots « du II ».")

add('137', '''
<p>La direction de l'établissement doit conserver les documents établis par les organisateurs et entrepreneurs de spectacles pour l'assiette et le contrôle de l'impôt : coupons de contrôle, souches de carnets, feuilles de location et d'abonnement, bordereaux des guichets de vente et plan indiquant les places occupées. Cette conservation s'impose jusqu'à la vérification des comptes par un agent des douanes et droits indirects, sans pouvoir dépasser le délai prévu au premier alinéa du I de l'article L. 102 B du livre des procédures fiscales (1).</p>
<p>(1) Se reporter également aux articles A 26-1 et A 26-2 du livre des procédures fiscales.</p>
''', "Réécriture à droit constant : la direction de l'établissement devient le sujet de l'obligation et l'énumération des pièces est séparée de la durée de conservation, dans le même alinéa. La note de renvoi est maintenue dans le texte intégral. Aucune réforme de fond des délais ou du contrôle fiscal n'est appliquée.", "Toutes les pièces de la source sont reprises, notamment les feuilles d'abonnement et le plan des places occupées. La conservation demeure exigée jusqu'à la vérification, avec le plafond du premier alinéa du I de l'article L. 102 B du LPF, et non un délai nouveau chiffré. Les renvois de la note aux articles A 26-1 et A 26-2 sont conservés. Le livre des procédures fiscales ne figure pas parmi les fichiers du corpus consultés ; ces trois références restent à vérifier dans ce livre, sans y substituer une durée supposée.")

assert len(sources) == 24
assert len(drafts) == 24
assert set(drafts) == {s['number'] for s in sources}
result = []
for s in sources:
    xml, reason, notes = drafts[s['number']]
    result.append({
        'code_id': s['code_id'],
        'source_id': s['source_id'],
        'source_sha256': s['source_sha256'],
        'number': s['number'],
        'proposed_xml': xml,
        'reason': reason,
        'review_notes': notes,
        'status': 'rewrite_draft',
    })
Path('answer.json').write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n')
print(f'answer.json : {len(result)} articles')
